fun main() = runBlocking {                    // only for main() and tests, never in app code
    val start = System.currentTimeMillis()

    val a = async { delay(1000); 2 }            // both start now
    val b = async { delay(1000); 3 }
    println("Sum: ${a.await() + b.await()}")    // Sum: 5 after about 1 s, not 2 s

    val job = launch {
        repeat(5) { i -> println("Working $i"); delay(300) }
    }
    delay(700)
    job.cancel()                                 // prints Working 0, 1, 2 then stops
    println("Took ${System.currentTimeMillis() - start} ms")
}

