suspend fun exportCsv(rows: List<Row>, out: File) = withContext(Dispatchers.IO) {
    out.bufferedWriter().use { writer ->
        for (row in rows) {
            ensureActive()                         // stop quickly if the user cancels
            writer.appendLine(row.toCsv())
        }
    }
}

