fun countdown(from: Int): Flow<Int> = flow {
    for (i in from downTo 0) {
        emit(i)
        delay(1000)
    }
}

fun main() = runBlocking {
    countdown(5)
        .filter { it % 2 == 1 }
        .map { "T-minus $it" }
        .onEach { println(it) }            // T-minus 5, T-minus 3, T-minus 1
        .collect()

    val f = flow { println("started"); emit(1) }
    f.first(); f.first()                     // prints "started" twice: cold
}

