fun ConnectivityManager.isOnline(): Flow<Boolean> = callbackFlow {
    val cb = object : ConnectivityManager.NetworkCallback() {
        override fun onAvailable(n: Network) { trySend(true) }
        override fun onLost(n: Network) { trySend(false) }
    }
    registerDefaultNetworkCallback(cb)
    awaitClose { unregisterNetworkCallback(cb) }
}.distinctUntilChanged()

data class CounterState(val count: Int = 0, val lastChangedBy: String = "")

class CounterViewModel : ViewModel() {
    private val _state = MutableStateFlow(CounterState())
    val state: StateFlow<CounterState> = _state.asStateFlow()

    fun increment(by: String) = _state.update { it.copy(count = it.count + 1, lastChangedBy = by) }
}

