suspend fun main() {
    var unsafe = 0
    val atomic = AtomicInteger(0)
    val mutex = Mutex()
    var locked = 0

    withContext(Dispatchers.Default) {
        repeat(1_000) {
            launch {
                repeat(100) {
                    unsafe++                              // lost updates
                    atomic.incrementAndGet()              // always correct
                    mutex.withLock { locked++ }           // always correct
                }
            }
        }
    }
    println("unsafe=$unsafe atomic=${atomic.get()} locked=$locked")   // unsafe < 100000
}

@Dao
interface OrderDao {
    @Insert suspend fun insertOrder(order: OrderEntity): Long
    @Insert suspend fun insertItems(items: List<OrderItemEntity>)
    @Query("DELETE FROM cart") suspend fun clearCart()

    @Transaction                                 // all three succeed or none do
    suspend fun placeOrder(order: OrderEntity, items: List<OrderItemEntity>) {
        val id = insertOrder(order)
        insertItems(items.map { it.copy(orderId = id) })
        clearCart()
    }
}

class Migrator(private val mutex: Mutex = Mutex()) {
    private var done = false
    suspend fun migrateOnce(block: suspend () -> Unit) = mutex.withLock {
        if (!done) { block(); done = true }
    }
}

@Test fun retriesThreeTimesWithBackoff() = runTest {
    val api = FakeApi(failuresBeforeSuccess = 2)
    val start = currentTime
    val result = retryWithBackoff(times = 3, initialDelay = 1_000) { api.call() }
    assertEquals("ok", result)
    assertEquals(3, api.calls)
    assertEquals(3_000, currentTime - start)      // 1 s + 2 s of virtual time, instant in reality
}

